## Solution
```cpp[]
class Solution{
  public:
    int compute(int ind, int currL, int maxL, vector<int> price, vector<int> &dp)
    {
        if(ind==maxL || maxL==0) return 0; 
        if(dp[currL]!=-1) return dp[currL];

        int b1=0,b2;
        if(maxL-ind-1>=0)
            b1=price[ind]+compute(ind,currL+ind+1,maxL-ind-1,price,dp);
        b2=compute(ind+1,currL,maxL,price,dp);

        return dp[currL]=max(b1,b2);
    }
    int rodCutting(vector<int> price, int n) 
    {
        vector<int> dp(n+1,-1);
        return compute(0,0,n,price,dp);
    }
};

```

